#include <cstdio>

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int darioWins = 0, xerxesWins = 0;

    for (int i = 0; i < n; ++i) {
        int d, x;
        scanf("%d %d", &d, &x);

        // A mão A vence a mão B se (A - B) mod 5 é 3 ou 4.
        // Ex.: 3 vence 0, pois (3 - 0) mod 5 = 3 (seta de 3 para 0).
        int diff = ((d - x) % 5 + 5) % 5;

        if (diff == 3 || diff == 4) ++darioWins;
        else ++xerxesWins;
    }

    printf(darioWins > xerxesWins ? "dario\n" : "xerxes\n");
    return 0;
}
